-- Create the users table for authentication.
-- UUIDs are generated by PostgreSQL to avoid application-side coordination.
CREATE TABLE users (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    email VARCHAR(255) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Explicit index for email lookups (the UNIQUE constraint already creates one,
-- but being explicit makes the intent clear for reviewers).
CREATE INDEX idx_users_email ON users(email);

-- Reusable trigger function to auto-update the updated_at column on row updates.
-- Created once and shared across tables that need this behaviour.
CREATE OR REPLACE FUNCTION update_updated_at()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trigger_users_updated_at
    BEFORE UPDATE ON users
    FOR EACH ROW EXECUTE FUNCTION update_updated_at();
